def sla_report(stats, sla):
    out = {}
    for label, rule in sla.items():
        s = stats.get(label)
        if s is None:
            out[label] = ['missing']
            continue
        fails = []
        if s['p95'] > rule['p95']:
            fails.append('p95')
        if s['error_pct'] > rule['error_pct']:
            fails.append('error_pct')
        if s['samples'] < rule['min_samples']:
            fails.append('samples')
        if fails:
            out[label] = fails
    return out

