coding.solution:
class PaymentApi:
    def __init__(self):
        self._by_key = {}

    def create(self, key, amount):
        if key in self._by_key:
            pid, amt = self._by_key[key]
            return (200, pid) if amt == amount else (409, None)
        pid = f'P{len(self._by_key) + 1}'
        self._by_key[key] = (pid, amount)
        return (201, pid)

    def count(self):
        return len(self._by_key)
